// Mensaje de confirmacion del apartado (HU-01).
//
// Los importes (precio, abonado, pendiente) se COPIAN de la API de la tienda:
// este nodo no calcula nada. Si el cliente no tiene correo, el mensaje va a la
// tienda para que avise por otra via (regla A5: el flujo no falla).
const entrada = $input.first().json ?? {};
const d = entrada.datos ?? entrada;

const euros = (n) => Number(n ?? 0).toFixed(2).replace('.', ',') + ' EUR';
const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = (s) => '<p>' + escapar(s).replace(/\n/g, '<br>') + '</p>';

// 'tienda' quiere decir 'la direccion de la tienda', que resuelve el
// subflujo de notificacion con el fichero de configuracion.
const emailTienda = 'tienda';
const producto = [d.producto, d.talla].filter(Boolean).join(' · ');

const cuerpoCliente = [
  'Hola ' + (d.cliente ?? '') + ',',
  '',
  'Has apartado ' + producto + ' por ' + euros(d.precio) + '.',
  '',
  'Abonado: ' + euros(d.abonado),
  'Te queda por pagar: ' + euros(d.pendiente),
  'Fecha limite para pagarlo: ' + (d.fecha_limite ?? ''),
  '',
  'Tienes 90 dias desde hoy para terminar el pago. Si se pasa el plazo, los zapatos',
  'vuelven a la tienda y lo abonado se convierte en un vale de compra.',
  '',
  'Gracias!',
  'Zapateria Paso Firme',
].join('\n');

const cuerpoTienda = [
  'No se ha podido avisar al cliente del apartado #' + (d.id ?? '') + ' (' + (d.cliente ?? '') + '): no tiene correo electronico.',
  '',
  'Apartado: ' + producto,
  'Abonado: ' + euros(d.abonado),
  'Pendiente: ' + euros(d.pendiente),
  'Fecha limite: ' + (d.fecha_limite ?? ''),
  '',
  'Avisale por telefono o por aqui.',
].join('\n');

const emailCliente = String(d.email ?? '').trim();
const esCliente = emailCliente.length > 0;

const mensaje = esCliente
  ? { canal: 'email', email: emailCliente, asunto: 'Tu apartado · Paso Firme', cuerpo: cuerpoCliente }
  : { canal: 'email', email: emailTienda, asunto: 'Apartado #' + (d.id ?? '') + ' · el cliente no tiene correo', cuerpo: cuerpoTienda };

return [{ json: { ...mensaje, cuerpo_html: html(mensaje.cuerpo), avisado_al_cliente: esCliente, apartado_id: d.id ?? null } }];
